'use client';

import { useState, useEffect } from 'react';

export default function Header() {
  const [isOpen, setIsOpen] = useState(false);
  const [statusText, setStatusText] = useState('Cargando estado...');
  const [isClosed, setIsClosed] = useState(false);

  // 1. Menú Móvil
  const toggleMenu = () => setIsOpen(!isOpen);
  const closeMenu = () => setIsOpen(false);

  // 2. Lógica del Estado en Vivo
  useEffect(() => {
    const updateBusinessStatus = () => {
      const now = new Date();
      const day = now.getDay(); // 0 = Domingo, 1 = Lunes, ..., 5 = Viernes, 6 = Sábado
      const hour = now.getHours();
      const minutes = now.getMinutes();
      const currentTime = hour + minutes / 60;

      // Horarios: Viernes (5), Sábado (6) y Domingo (0) de 17:00 a 22:30
      const openDays = [5, 6, 0];
      const openHour = 17.0; // 5:00 PM
      const closeHour = 22.5; // 10:30 PM

      const isOpenDay = openDays.includes(day);
      const isOpenHours = currentTime >= openHour && currentTime < closeHour;

      if (isOpenDay && isOpenHours) {
        setIsClosed(false);
        setStatusText('Masa leudando • Horno Encendido');
      } else {
        setIsClosed(true);
        if (isOpenDay && currentTime < openHour) {
          setStatusText('Horno Apagado • Abrimos hoy a las 5:00 PM');
        } else {
          setStatusText('Horno Apagado • Abrimos el Viernes');
        }
      }
    };

    updateBusinessStatus();
    const interval = setInterval(updateBusinessStatus, 60000);
    return () => clearInterval(interval);
  }, []);

  return (
    <header className="header">
      <nav className="nav" aria-label="Navegación principal">
        <a href="#" className="logo" onClick={closeMenu}>
          CasiPizza
        </a>

        <ul className={`nav-links ${isOpen ? 'is-open' : ''}`} id="nav-links">
          <li>
            <a href="#historia" onClick={closeMenu}>Nuestra masa</a>
          </li>
          <li>
            <a href="#menu" onClick={closeMenu}>Menú</a>
          </li>
          <li>
            <a href="#horarios" onClick={closeMenu}>Horarios</a>
          </li>
        </ul>

        <div className={`live-badge live-badge--sm ${isClosed ? 'is-closed' : ''}`} id="status-badge">
          <span className="live-dot" id="status-dot"></span>
          <span className="live-text" id="status-text">{statusText}</span>
        </div>

        <button
          className="nav-toggle"
          onClick={toggleMenu}
          aria-label="Abrir menú de navegación"
          aria-expanded={isOpen}
          aria-controls="nav-links"
        >
          <svg className="icon-closed" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            <circle cx="12" cy="12" r="10"></circle>
            <line x1="12" y1="2" x2="12" y2="22"></line>
            <line x1="2" y1="12" x2="22" y2="12"></line>
            <line x1="4.93" y1="4.93" x2="19.07" y2="19.07"></line>
            <line x1="19.07" y1="4.93" x2="4.93" y2="19.07"></line>
          </svg>
          <svg className="icon-open" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            <path d="M15 11h.01"></path>
            <path d="M11 15h.01"></path>
            <path d="M16 16h.01"></path>
            <path d="m2 16 20 6-6-20A20 20 0 0 0 2 16"></path>
            <path d="M5.71 17.11a17.04 17.04 0 0 1 11.4-11.4"></path>
          </svg>
        </button>
      </nav>
    </header>
  );
}